package com.payshift.merchant.provider;

import java.math.BigDecimal;

/**
 * Port for the Razorpay integration, mirroring the shape of StripePaymentGateway
 * so both providers follow the same calling convention from their respective
 * services, without forcing Razorpay's implementation to share Stripe's interface.
 */
public interface RazorpayPaymentGateway {

    ProviderOrderResult createOrder(String orderReference, BigDecimal amount, String currency);

    ProviderRefundResult createRefund(String providerPaymentId, BigDecimal amount);

    record ProviderOrderResult(String providerPaymentId, String status) {
    }

    record ProviderRefundResult(String providerRefundId, String status) {
    }
}

package com.payshift.merchant.provider;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestTemplate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Map;

/**
 * Real REST client integration against Razorpay's documented Orders/Payments API
 * (no official Razorpay Java SDK dependency was added; a typed REST client was
 * used instead, per the "no suitable SDK" fallback). Not exercised in the test
 * suite, which mocks RazorpayPaymentGateway -- this class is never called with
 * live credentials during tests.
 */
@Component
public class RazorpayApiPaymentGateway implements RazorpayPaymentGateway {

    private static final String BASE_URL = "https://api.razorpay.com/v1";

    private final RestTemplate restTemplate = new RestTemplate();
    private final String keyId;
    private final String keySecret;

    public RazorpayApiPaymentGateway(
            @Value("${payshift.razorpay.key-id:rzp_test_placeholder}") String keyId,
            @Value("${payshift.razorpay.key-secret:placeholder_secret}") String keySecret) {
        this.keyId = keyId;
        this.keySecret = keySecret;
    }

    private static long toMinorUnits(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.HALF_UP).movePointRight(2).longValueExact();
    }

    private HttpHeaders authHeaders() {
        HttpHeaders headers = new HttpHeaders();
        headers.setBasicAuth(keyId, keySecret);
        headers.setContentType(MediaType.APPLICATION_JSON);
        return headers;
    }

    @Override
    public ProviderOrderResult createOrder(String orderReference, BigDecimal amount, String currency) {
        Map<String, Object> body = Map.of(
                "amount", toMinorUnits(amount),
                "currency", currency.toUpperCase(),
                "receipt", orderReference
        );
        ResponseEntity<Map> response = restTemplate.postForEntity(
                BASE_URL + "/orders", new HttpEntity<>(body, authHeaders()), Map.class);
        Map<?, ?> responseBody = response.getBody();
        if (responseBody == null) {
            throw new ProviderCallException("Razorpay order creation returned no body", null);
        }
        return new ProviderOrderResult((String) responseBody.get("id"), (String) responseBody.get("status"));
    }

    @Override
    public ProviderRefundResult createRefund(String providerPaymentId, BigDecimal amount) {
        Map<String, Object> body = Map.of("amount", toMinorUnits(amount));
        ResponseEntity<Map> response = restTemplate.postForEntity(
                BASE_URL + "/payments/" + providerPaymentId + "/refund",
                new HttpEntity<>(body, authHeaders()), Map.class);
        Map<?, ?> responseBody = response.getBody();
        if (responseBody == null) {
            throw new ProviderCallException("Razorpay refund creation returned no body", null);
        }
        return new ProviderRefundResult((String) responseBody.get("id"), (String) responseBody.get("status"));
    }
}

package com.payshift.merchant.service;

import com.payshift.merchant.domain.Order;
import com.payshift.merchant.domain.Payment;
import com.payshift.merchant.domain.PaymentStatus;
import com.payshift.merchant.domain.Refund;
import com.payshift.merchant.provider.RazorpayPaymentGateway;
import com.payshift.merchant.repository.OrderRepository;
import com.payshift.merchant.repository.PaymentRepository;
import com.payshift.merchant.repository.RefundRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;

/**
 * Added alongside PaymentService (Stripe) rather than merged into it: the existing
 * service stays untouched so its behavior and tests are provably unaffected.
 */
@Service
public class RazorpayPaymentService {

    private static final String PROVIDER_ID = "razorpay";

    private final PaymentRepository paymentRepository;
    private final OrderRepository orderRepository;
    private final RefundRepository refundRepository;
    private final RazorpayPaymentGateway razorpayGateway;

    public RazorpayPaymentService(PaymentRepository paymentRepository,
                                   OrderRepository orderRepository,
                                   RefundRepository refundRepository,
                                   RazorpayPaymentGateway razorpayGateway) {
        this.paymentRepository = paymentRepository;
        this.orderRepository = orderRepository;
        this.refundRepository = refundRepository;
        this.razorpayGateway = razorpayGateway;
    }

    @Transactional
    public Payment createPayment(String orderReference, BigDecimal amount, String currency, String idempotencyKey) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> {
                    Order order = orderRepository.findByOrderReference(orderReference)
                            .orElseGet(() -> orderRepository.save(new Order(orderReference, amount, currency)));

                    RazorpayPaymentGateway.ProviderOrderResult result =
                            razorpayGateway.createOrder(orderReference, amount, currency);

                    PaymentStatus status = "paid".equals(result.status())
                            ? PaymentStatus.SUCCEEDED
                            : "created".equals(result.status()) || "attempted".equals(result.status())
                                ? PaymentStatus.REQUIRES_ACTION
                                : PaymentStatus.FAILED;

                    Payment payment = new Payment(order.getId(), PROVIDER_ID, result.providerPaymentId(),
                            idempotencyKey, amount, currency, status);
                    return paymentRepository.save(payment);
                });
    }

    public Payment getByProviderPaymentId(String providerPaymentId) {
        return paymentRepository.findByProviderPaymentId(providerPaymentId)
                .orElseThrow(() -> new PaymentNotFoundException("No payment for provider payment id " + providerPaymentId));
    }

    @Transactional
    public Refund refund(String providerPaymentId, BigDecimal requestedAmount) {
        Payment payment = getByProviderPaymentId(providerPaymentId);

        if (!PROVIDER_ID.equals(payment.getProvider())) {
            throw new InvalidRefundException(
                    "Payment " + providerPaymentId + " is owned by provider '" + payment.getProvider()
                            + "', not razorpay; refunds must be routed to the provider that owns the payment.");
        }
        if (payment.getStatus() != PaymentStatus.SUCCEEDED && payment.getStatus() != PaymentStatus.PARTIALLY_REFUNDED) {
            throw new InvalidRefundException("Cannot refund a payment that has not succeeded: " + payment.getStatus());
        }

        BigDecimal amount = requestedAmount != null ? requestedAmount : payment.getRefundableAmount();
        if (amount.signum() <= 0) {
            throw new InvalidRefundException("Refund amount must be positive");
        }
        if (amount.compareTo(payment.getRefundableAmount()) > 0) {
            throw new InvalidRefundException("Refund amount exceeds refundable balance");
        }

        RazorpayPaymentGateway.ProviderRefundResult result = razorpayGateway.createRefund(providerPaymentId, amount);

        payment.applyRefund(amount);
        paymentRepository.save(payment);

        Refund refund = new Refund(payment.getId(), payment.getProvider(), result.providerRefundId(), amount);
        return refundRepository.save(refund);
    }
}

package com.payshift.merchant.controller;

import com.payshift.merchant.domain.Payment;
import com.payshift.merchant.domain.Refund;
import com.payshift.merchant.dto.CreatePaymentRequest;
import com.payshift.merchant.dto.PaymentResponse;
import com.payshift.merchant.dto.RefundRequest;
import com.payshift.merchant.dto.RefundResponse;
import com.payshift.merchant.service.RazorpayPaymentService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Additive: existing /api/payments (Stripe) endpoints are untouched. */
@RestController
@RequestMapping("/api/payments/razorpay")
public class RazorpayPaymentController {

    private final RazorpayPaymentService paymentService;

    public RazorpayPaymentController(RazorpayPaymentService paymentService) {
        this.paymentService = paymentService;
    }

    @PostMapping
    public ResponseEntity<PaymentResponse> createPayment(@Valid @RequestBody CreatePaymentRequest request) {
        Payment payment = paymentService.createPayment(
                request.orderReference(), request.amount(), request.currency(), request.idempotencyKey());
        return ResponseEntity.status(HttpStatus.CREATED).body(PaymentResponse.from(payment));
    }

    @GetMapping("/{providerPaymentId}")
    public ResponseEntity<PaymentResponse> getPaymentStatus(@PathVariable String providerPaymentId) {
        Payment payment = paymentService.getByProviderPaymentId(providerPaymentId);
        return ResponseEntity.ok(PaymentResponse.from(payment));
    }

    @PostMapping("/{providerPaymentId}/refunds")
    public ResponseEntity<RefundResponse> refundPayment(@PathVariable String providerPaymentId,
                                                          @RequestBody RefundRequest request) {
        Refund refund = paymentService.refund(providerPaymentId, request.amount());
        return ResponseEntity.status(HttpStatus.CREATED).body(RefundResponse.from(refund));
    }
}

package com.payshift.merchant.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.payshift.merchant.domain.ProcessedWebhookEvent;
import com.payshift.merchant.repository.PaymentRepository;
import com.payshift.merchant.repository.ProcessedWebhookEventRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.InvalidKeyException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/** Razorpay verifies webhooks with HMAC-SHA256 over the raw request body, unlike
 * Stripe's "timestamp.body" scheme -- each provider's webhook handler keeps its
 * own correct verification logic rather than sharing one generic implementation. */
@Service
public class RazorpayWebhookService {

    private static final Logger log = LoggerFactory.getLogger(RazorpayWebhookService.class);
    private static final String PROVIDER_ID = "razorpay";

    private final PaymentRepository paymentRepository;
    private final ProcessedWebhookEventRepository processedWebhookEventRepository;
    private final OrderFulfillmentService orderFulfillmentService;
    private final String webhookSecret;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public RazorpayWebhookService(PaymentRepository paymentRepository,
                                   ProcessedWebhookEventRepository processedWebhookEventRepository,
                                   OrderFulfillmentService orderFulfillmentService,
                                   @Value("${payshift.razorpay.webhook-secret:razorpay_test_placeholder}") String webhookSecret) {
        this.paymentRepository = paymentRepository;
        this.processedWebhookEventRepository = processedWebhookEventRepository;
        this.orderFulfillmentService = orderFulfillmentService;
        this.webhookSecret = webhookSecret;
    }

    public void verifySignature(String payload, String signatureHeader) {
        String expected = hmacSha256Hex(webhookSecret, payload);
        if (!constantTimeEquals(expected, signatureHeader)) {
            throw new InvalidWebhookSignatureException("Invalid Razorpay webhook signature", null);
        }
    }

    @Transactional
    public boolean processEvent(String payload) {
        JsonNode root;
        try {
            root = objectMapper.readTree(payload);
        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
            throw new IllegalStateException("Malformed Razorpay webhook payload", e);
        }

        String event = root.path("event").asText("");
        String providerPaymentId = root.path("payload").path("payment").path("entity").path("id").asText(null);
        String eventId = root.path("id").asText(null);
        if (eventId == null) {
            eventId = event + ":" + (providerPaymentId != null ? providerPaymentId : "unknown");
        }

        if (processedWebhookEventRepository.existsByEventId(eventId)) {
            log.info("Ignoring duplicate Razorpay webhook delivery for event {}", eventId);
            return false;
        }

        if ("payment.captured".equals(event) && providerPaymentId != null) {
            paymentRepository.findByProviderPaymentId(providerPaymentId).ifPresent(payment -> {
                payment.markSucceeded();
                paymentRepository.save(payment);
                orderFulfillmentService.fulfill(payment.getOrderId());
            });
        } else if ("payment.failed".equals(event) && providerPaymentId != null) {
            paymentRepository.findByProviderPaymentId(providerPaymentId).ifPresent(payment -> {
                payment.markFailed();
                paymentRepository.save(payment);
            });
        } else {
            log.info("Ignoring unhandled Razorpay event type {}", event);
        }

        processedWebhookEventRepository.save(new ProcessedWebhookEvent(eventId, PROVIDER_ID));
        return true;
    }

    private static String hmacSha256Hex(String secret, String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            byte[] hash = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (NoSuchAlgorithmException | InvalidKeyException e) {
            throw new RuntimeException(e);
        }
    }

    private static boolean constantTimeEquals(String a, String b) {
        if (a == null || b == null) {
            return false;
        }
        return MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8), b.getBytes(StandardCharsets.UTF_8));
    }
}

package com.payshift.merchant.controller;

import com.payshift.merchant.service.RazorpayWebhookService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/webhooks")
public class RazorpayWebhookController {

    private final RazorpayWebhookService webhookService;

    public RazorpayWebhookController(RazorpayWebhookService webhookService) {
        this.webhookService = webhookService;
    }

    @PostMapping("/razorpay")
    public ResponseEntity<String> handleRazorpayWebhook(@RequestBody String payload,
                                                          @RequestHeader("X-Razorpay-Signature") String signatureHeader) {
        webhookService.verifySignature(payload, signatureHeader);
        boolean processed = webhookService.processEvent(payload);
        return ResponseEntity.ok(processed ? "processed" : "duplicate_ignored");
    }
}

package com.payshift.merchant;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.payshift.merchant.provider.RazorpayPaymentGateway;
import com.payshift.merchant.provider.StripePaymentGateway;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class RazorpayPaymentFlowIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @MockBean
    private RazorpayPaymentGateway razorpayGateway;

    @MockBean
    private StripePaymentGateway stripeGateway;

    @Test
    void createPayment_succeeds_viaRazorpay() throws Exception {
        String orderId = "order_" + UUID.randomUUID();
        when(razorpayGateway.createOrder(any(), any(), any()))
                .thenReturn(new RazorpayPaymentGateway.ProviderOrderResult(orderId, "paid"));

        mockMvc.perform(post("/api/payments/razorpay")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of(
                                "orderReference", "rp-order-1",
                                "amount", "40.00",
                                "currency", "inr",
                                "idempotencyKey", "rp-idem-1"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.provider").value("razorpay"))
                .andExpect(jsonPath("$.status").value("SUCCEEDED"));
    }

    @Test
    void refund_rejectsWhenPaymentBelongsToADifferentProvider() throws Exception {
        String piId = "pi_" + UUID.randomUUID();
        when(stripeGateway.createPaymentIntent(any(), any(), any()))
                .thenReturn(new StripePaymentGateway.ProviderPaymentResult(piId, "succeeded", "secret"));

        mockMvc.perform(post("/api/payments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of(
                                "orderReference", "rp-order-2",
                                "amount", "40.00",
                                "currency", "usd",
                                "idempotencyKey", "rp-idem-2"))))
                .andExpect(status().isCreated());

        mockMvc.perform(post("/api/payments/razorpay/" + piId + "/refunds")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isUnprocessableEntity());
    }
}
